// A single call covering every sheet in a large workbook can run long
// enough to trip n8n's gateway timeout (502), so the caller pages through
// sheets chunk_size at a time via offset/limit in the webhook body.
const body = $('Webhook').first().json.body;
const offset = Number(body.offset ?? 0);
const limit = Number(body.limit ?? 1000);
return $input.all().slice(offset, offset + limit);

const output = [];
for (const item of $input.all()) {
  const sheet = item.json.data.address.split('!')[0].replace(/^'|'$/g, '');
  const rows = item.json.data.values ?? [];
  for (const row of rows) {
    const dtc = row[0];
    if (!dtc) continue; // skips the leftover sub-header row and blank padding rows within the fixed A3:H5000 range
    output.push({
      json: {
        sheet,
        dtc,
        description: row[1],
        warning_light: row[2],
        warning_message: row[3],
        limp_home: row[4],
        fail_safe: row[5],
        grade: row[6],
        grading_background: row[7],
      },
    });
  }
}
return output;

// Collects every row whose sheet wasn't found in the static MAPPING above,
// shaped to match the AI Agent prompt below: {sheet, top_candidates, samples}
// with samples as {dtc, description} objects. top_candidates is always []
// here -- real candidate voting needs the reference sqlite DB
// (tools/review_context.py's count_sheet_candidates), which n8n Cloud has
// no access to, so the AI can only go on the sheet name + samples for
// sheets reached through this path. Outputs 0 items (no AI call, no
// suggestions in the response) when every sheet was already mapped.
const bySheet = {};
for (const item of $input.all()) {
  const row = item.json;
  if (row.system) continue;
  if (!bySheet[row.sheet]) bySheet[row.sheet] = [];
  if (bySheet[row.sheet].length < 8) {
    bySheet[row.sheet].push({ dtc: row.dtc, description: row.description });
  }
}
const sheets = Object.entries(bySheet).map(([sheet, samples]) => ({
  sheet,
  top_candidates: [],
  samples,
}));
if (sheets.length === 0) return [];
return [{ json: { sheets } }];

const sheets = $('Build Unmapped Sheets Summary').first().json.sheets;
const text = $json.output ?? $json.text ?? '';
let parsed;
try {
  parsed = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new Error('not an array');
} catch (e) {
  parsed = sheets.map((s) => ({
    sheet: s.sheet,
    suggested_system: '',
    reasoning: 'AI 응답을 JSON 배열로 파싱하지 못함: ' + text,
  }));
}
return [{ json: { suggestions: parsed } }];

// Merge Branches gives us 1 item ({rows: [...]}) when every sheet was
// mapped, or 2 items ({rows: [...]}, {suggestions: [...]}) when some
// weren't -- either way, collapse into a single response object.
// totalSheets (from the full, unsliced list) lets the caller know when
// it's paged through every sheet.
const merged = {};
for (const item of $input.all()) Object.assign(merged, item.json);
merged.totalSheets = $('Get Sheets').all().length;
return [{ json: merged }];
